import {trafficMessage} from './messages.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>trafficMessage(k,I18n.language),fmt=n=>Number.isFinite(n)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:4}).format(n):'—';
export class TrafficController{
 constructor(container,repository,service,{isOpen=()=>false,onChange=()=>{}}={}){Object.assign(this,{container,repository,service,isOpen,onChange,manifest:null,map:null,layer:null,result:null,point:{lat:'',lon:''},show:false,opacity:.7,error:false,generation:0});container.dataset.userContent='';container.addEventListener('change',e=>{if(e.target.dataset.traffic==='show'){this.show=e.target.checked;this.render();}if(e.target.dataset.traffic==='opacity'){this.opacity=Number(e.target.value);this.layer?.setOpacity(this.opacity);}});container.addEventListener('input',e=>{if(e.target.dataset.traffic==='opacity'){this.opacity=Number(e.target.value);this.layer?.setOpacity(this.opacity);}if(e.target.name==='latitude'||e.target.name==='longitude'){++this.generation;this.result=null;this.marker?.remove();this.marker=null;this.container.querySelector('[data-traffic-result]')?.replaceChildren();}});container.addEventListener('click',e=>{if(e.target.closest('[data-traffic-action=fit]'))this.fit();});container.addEventListener('submit',e=>{e.preventDefault();this.point={lat:e.target.elements.latitude.value,lon:e.target.elements.longitude.value};this.query(Number(this.point.lat),Number(this.point.lon));});this.render();}
 async restore(){try{this.manifest=await this.repository.open();this.error=false;this.render();this.onChange();}catch{this.error=true;this.render();}}
 attachMap(map){if(this.map===map)return;this.map=map;map.on('click',e=>{if(this.isOpen())this.query(e.latlng.lat,e.latlng.lng);});this.draw();}
 async query(lat,lon){const generation=++this.generation;this.point={lat:String(lat),lon:String(lon)};this.result='loading';this.render();const result=await this.service.getTransitValue(lat,lon,'2025-01-01',{temporalMode:'annual-background'});if(generation===this.generation){this.result=result;this.marker?.remove();this.marker=this.map?window.L.circleMarker([lat,lon],{radius:7,color:'#fff',weight:2,fillColor:'#b97a37',fillOpacity:1}).addTo(this.map):null;this.render();this.container.querySelector('[data-traffic-result]')?.scrollIntoView({block:'nearest'});}}
 render(){const m=this.manifest,r=this.result;this.container.innerHTML=`<div class="observation-intro"><span class="workbench-tag">${esc(t('subtitle'))}</span><h3>${esc(t('title'))}</h3><p>${esc(t('intro'))}</p></div>${this.error?`<p role="status">${esc(t('error'))}</p>`:''}${m?`<label class="environment-checkbox"><input type="checkbox" data-traffic="show" ${this.show?'checked':''}><span>${esc(t('show'))}</span></label><label>${esc(t('opacity'))}<input type="range" min="0" max="1" step="0.05" value="${this.opacity}" data-traffic="opacity"></label><div class="traffic-colorbar"></div><div class="traffic-scale"><span>1</span><span>≥${fmt(m.overview.scaleMax)}</span></div><button class="btn secondary full" data-traffic-action="fit">${esc(t('fit'))}</button><form class="environment-query"><h3>${esc(t('query'))}</h3><p>${esc(t('hint'))}</p><div class="environment-coordinate-fields"><label>${esc(t('lat'))}<input type="number" name="latitude" min="-90" max="90" required step="any" value="${esc(this.point.lat)}"></label><label>${esc(t('lon'))}<input type="number" name="longitude" min="-180" max="180" required step="any" value="${esc(this.point.lon)}"></label></div><button class="btn secondary full">${esc(t('query'))}</button></form><div data-traffic-result role="status">${r==='loading'?esc(t('loading')):r?`<strong class="traffic-value">${r.status==='available'?fmt(r.value):'—'}</strong><p>${esc(r.status==='available'?t('count'):t(r.status)===r.status?t('unavailable'):t(r.status))}</p>${r.gridCell?`<p>${fmt(r.gridCell.latitude)} / ${fmt(r.gridCell.longitude)} · row${r.gridCell.row} / col${r.gridCell.column}</p>`:''}`:''}</div><details class="environment-notes"><summary>${esc(t('source'))}</summary><p>${esc(t('native'))}</p><p>${esc(t('display'))}</p><p>${esc(t('conflict'))}</p><p>${esc(t('noLive'))}</p><p>${esc(m.source.attribution)}</p><p class="small-note">SHA-256 ${esc(m.source.sha256)}</p><a href="${esc(m.source.url)}" target="_blank" rel="noopener">NOAA · 2025 ↗</a></details>`:''}`;this.draw();const badge=document.getElementById('trafficOverlayBadge');if(badge){badge.hidden=!this.show||!m;badge.textContent=t('subtitle');}}
 draw(){if(!this.map||!this.manifest)return;if(this.layer)this.map.removeLayer(this.layer);this.layer=null;if(!this.show)return;const m=this.manifest,b=m.overview.bbox,url=new URL(m.overview.file,this.repository.url);url.searchParams.set('revision',m.revision);this.layer=window.L.imageOverlay(url.href,[[b[1],b[0]],[b[3],b[2]]],{opacity:this.opacity,interactive:false,attribution:'NOAA AIS · annual2025 · max16×16 display'}).addTo(this.map);}
 fit(){if(!this.map||!this.manifest)return;const b=this.manifest.overview.bbox;this.show=true;this.map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{padding:[35,35],maxZoom:7});this.render();}
}
